{"path": "src/server.js", "content": "const express = require('express');
const dotenv = require('dotenv');
const { fetchCustomerContext, vectorSearchByEmbedding, buildRationale } = require('./agent');

dotenv.config();
const app = express();
const PORT = process.env.PORT || 3000;

app.get('/search', async (req, res) => {
  try {
    const customerId = req.query.customerId;
    if (!customerId) return res.status(400).json({ error: 'customerId is required' });

    const { profile, segment, recentInteractions } = await fetchCustomerContext(customerId);
    if (!profile) return res.status(404).json({ error: 'customer not found' });

    // For the sample, use the latest interaction's embedding as the query vector
    const queryEmbedding = (recentInteractions && recentInteractions[0] && recentInteractions[0].embedding) || null;
    if (!queryEmbedding) return res.status(422).json({ error: 'no interaction embedding available to form query' });

    const topResults = await vectorSearchByEmbedding(queryEmbedding, 5);
    const rationale = buildRationale(profile, segment, topResults);

    return res.json({ customerId, profile, segment, topResults, rationale });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: String(err) });
  }
});

app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
"}

